203	    /**
204	     * The owner's age band derived from {@link #birthDate} relative to the
205	     * {@link #registrationDate}: {@code 'MINOR'} when under 18, {@code 'ADULT'} from 18 to 64,
206	     * and {@code 'SENIOR'} at 65 or older. Returns {@code null} when no birthDate is set. The age
207	     * is the number of complete years between the birthDate and the registrationDate (or the
208	     * current date when the registrationDate is not yet set).
209	     */
210	    public String getAgeBand() {
211	        if (this.birthDate == null) {
212	            return null;
213	        }
214	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
215	        int years = Period.between(this.birthDate, reference).getYears();
216	        if (years < 18) {
217	            return "MINOR";
218	        }
219	        if (years < 65) {
220	            return "ADULT";
221	        }
222	        return "SENIOR";
223	    }
