317	    /**
318	     * The canonical URL path of this owner: {@code '/api/owners/'} followed by the owner's
319	     * {@linkplain #getId() id}, e.g. {@code '/api/owners/1'}.
320	     */
321	    public String getSelfLink() {
322	        return "/api/owners/" + this.getId();
323	    }
324	
325	    /**
326	     * The owner's initials: the upper-cased first letters of firstName and lastName,
327	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
328	     */
329	    public String getInitials() {
330	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
331	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
332	    }
333	
334	    /**
335	     * The fixed length of the tail that every {@linkplain #getMemberId() memberId} carries after its
336	     * {@code <REGION>} prefix: the 2-digit fiscal-year code, the 8-character HASH8 and the single Luhn
337	     * check digit ({@code 2 + 8 + 1 = 11}). The region prefix is therefore everything in the memberId
338	     * (before any collision suffix) up to this trailing block, so the region and fiscal-year segments
339	     * are read back from the memberId rather than re-derived.
340	     */
341	    private static final int MEMBER_ID_TAIL = 11;
342	
343	    /**
344	     * The owner's base memberId, formatted {@code '<REGION><FY><HASH8><CHK>'}: the
345	     * {@linkplain #getRegion() region} derived from the owner's postcode (or {@link #UNKNOWN_REGION}
346	     * when the postcode maps to no known region), the 2-digit {@linkplain #fiscalYearCode() fiscal-year
347	     * code} FY, the 8 upper-case hex HASH8 (the first 8 hex characters of the SHA-256 of the normalized
348	     * (E.164) telephone concatenated with the lastName, the same HASH8 the region-and-hash identity
349	     * uses), and a single Luhn {@linkplain #luhnCheckDigit(String) check digit} CHK computed over the
350	     * decimal digits of {@code <REGION><FY><HASH8>}, e.g. {@code 'NSW273C1A9F2B4'}. This is the single
351	     * source of the owner's identity; the stored {@linkplain #getMemberId() memberId} is this value
352	     * (with a collision suffix appended only when it clashes with an existing owner's), and the owner's
353	     * {@linkplain #getLocality() locality} and {@linkplain #getFiscalYear() fiscal year} are read back
354	     * from it.
355	     */
356	    public String computeMemberId() {
357	        String region = getRegion() != null ? getRegion() : UNKNOWN_REGION;
358	        String hash8 = HashUtils.sha256Hex(this.telephone + this.getLastName()).toUpperCase().substring(0, 8);
359	        String prefix = region + fiscalYearCode() + hash8;
360	        return prefix + luhnCheckDigit(prefix);
361	    }
362	
363	    /**
364	     * The {@linkplain #getMemberId() memberId} without its collision suffix: the memberId up to the
365	     * first {@code '-'} (the {@code '-<n>'} suffix appended only to de-duplicate a clashing id), or
366	     * {@code null} when the owner has no memberId. This is the {@code '<REGION><FY><HASH8><CHK>'} base
367	     * from which the {@linkplain #getLocality() locality} and {@linkplain #getFiscalYear() fiscal year}
368	     * are read.
369	     */
370	    private String memberIdBase() {
371	        if (this.memberId == null) {
372	            return null;
373	        }
374	        int dash = this.memberId.indexOf('-');
375	        return dash < 0 ? this.memberId : this.memberId.substring(0, dash);
376	    }
377	
378	    /**
379	     * The owner's fiscal year, formatted {@code 'FY<YY>'}, e.g. {@code 'FY27'}. The two YY digits are
380	     * read from the {@linkplain #getMemberId() memberId} (the {@code <FY>} segment embedded in it), so
381	     * the fiscal-year value shares the owner's single memberId identity; for an owner that has no
382	     * memberId the digits fall back to the {@linkplain #fiscalYearCode() fiscal-year code} of the
383	     * (business-day-adjusted) {@link #registrationDate}. The fiscal year starts on 1 July and is
384	     * labelled by the calendar year in which it ends.
385	     */
386	    public String getFiscalYear() {
387	        String base = memberIdBase();
388	        if (base != null && base.length() >= MEMBER_ID_TAIL) {
389	            return "FY" + base.substring(base.length() - MEMBER_ID_TAIL, base.length() - MEMBER_ID_TAIL + 2);
390	        }
391	        return "FY" + fiscalYearCode();
392	    }
393	
394	    /**
395	     * The two-digit fiscal-year code {@code '<YY>'}: the last two digits of the
396	     * {@linkplain #fiscalYearOf(LocalDate) fiscal year} of the (business-day-adjusted)
397	     * {@link #registrationDate}, zero-padded, e.g. {@code '27'}. This is the FY segment embedded in the
398	     * owner's {@linkplain #computeMemberId() memberId} at creation, and the fallback the
399	     * {@linkplain #getFiscalYear() fiscal year} reads when no memberId is present.
400	     */
401	    private String fiscalYearCode() {
402	        return String.format("%02d", fiscalYearOf(this.registrationDate) % 100);
403	    }
404	
405	    /**
406	     * The fiscal year that contains the given date, identified by the calendar year in which it
407	     * ends. The fiscal year starts on 1 July, so a date in July through December belongs to the
408	     * fiscal year ending in the following calendar year, while a date in January through June
409	     * belongs to the fiscal year ending in the same calendar year.
410	     */
411	    private static int fiscalYearOf(LocalDate date) {
412	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
413	    }
414	
415	    /**
416	     * The Luhn check digit (a single digit, {@code 0}-{@code 9}) over the decimal digits
417	     * contained in {@code value}. Reading the digits right to left, every second one is
418	     * doubled (subtracting 9 whenever doubling yields a value above 9); the transformed
419	     * digits are summed, and the check digit is the amount that must be added to that sum to
420	     * reach the next multiple of ten. Any non-digit character in {@code value} is ignored, so
421	     * the digit is taken over exactly the digits the string carries.
422	     */
423	    private static int luhnCheckDigit(String value) {
424	        int sum = 0;
425	        boolean doubling = true;
426	        for (int i = value.length() - 1; i >= 0; i--) {
427	            char c = value.charAt(i);
428	            if (c < '0' || c > '9') {
429	                continue;
430	            }
431	            int digit = c - '0';
432	            if (doubling) {
433	                digit *= 2;
434	                if (digit > 9) {
435	                    digit -= 9;
436	                }
437	            }
438	            sum += digit;
439	            doubling = !doubling;
440	        }
441	        return (10 - (sum % 10)) % 10;
442	    }
443	
444	    /** Fixed city-to-region table used to derive an owner's locality. */
445	    private static final Map<String, String> CITY_REGION = Map.of(
446	        "Sydney", "NSW",
447	        "Melbourne", "VIC",
448	        "Brisbane", "QLD");
449	
450	    /** The region reported for a city that is not present in {@link #CITY_REGION}. */
451	    public static final String UNKNOWN_REGION = "UNKNOWN";
452	
453	    /**
454	     * The canonical region for a city, derived from the fixed city-to-region table
455	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), or
456	     * {@link #UNKNOWN_REGION} when the city is not in the table. This is the single
457	     * source of the city-to-region mapping, shared by every rule that is keyed by
458	     * region so the mapping is never re-derived elsewhere.
459	     */
460	    public static String regionOf(String city) {
461	        return CITY_REGION.getOrDefault(city, UNKNOWN_REGION);
462	    }
463	
464	    /**
465	     * The owner's locality: the {@code <REGION>} component of the {@link #getMemberId() memberId} (its
466	     * prefix before the trailing {@code <FY><HASH8><CHK>} block), which is the region derived from the
467	     * owner's postcode at creation ({@link #UNKNOWN_REGION} when the postcode maps to no known region).
468	     * Locality is read from the memberId identity so it never re-derives a region of its own; it is
469	     * {@link #UNKNOWN_REGION} for an owner that has no memberId.
470	     */
471	    public String getLocality() {
472	        String base = memberIdBase();
473	        if (base == null || base.length() <= MEMBER_ID_TAIL) {
474	            return UNKNOWN_REGION;
475	        }
476	        return base.substring(0, base.length() - MEMBER_ID_TAIL);
477	    }
478	
479	    /** Fixed region-to-timezone table, mapping a region to its IANA timezone name. */
480	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
481	        "NSW", "Australia/Sydney",
482	        "VIC", "Australia/Melbourne",
483	        "QLD", "Australia/Brisbane");
484	
485	    /**
486	     * The owner's timezone: the IANA name for this owner's {@linkplain #getLocality() locality},
487	     * looked up in the fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
488	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}), or {@code null} when
489	     * the locality maps to no known region (e.g. {@link #UNKNOWN_REGION}). It reads the locality
490	     * rather than re-deriving a region so the timezone shares the owner's single region identity.
491	     */
492	    public String getTimezone() {
493	        return REGION_TIMEZONE.get(getLocality());
494	    }
495	
496	    /**
497	     * The owner's segment, formatted {@code '<TIER>_<AREA>'}, one of {@code 'PREMIUM_METRO'},
498	     * {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or {@code 'STANDARD_REGIONAL'}. TIER is
499	     * {@code 'PREMIUM'} when {@linkplain #getMembershipLevel() membershipLevel} is 3 or more,
500	     * otherwise {@code 'STANDARD'}. AREA is {@code 'METRO'} when the owner's
501	     * {@linkplain #getLocality() locality} is a known region (NSW, VIC or QLD), otherwise
502	     * {@code 'REGIONAL'}. It reads the locality against the shared region table so it never
503	     * re-derives a region of its own.
504	     */
505	    public String getOwnerSegment() {
506	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
507	        String area = REGION_TIMEZONE.containsKey(getLocality()) ? "METRO" : "REGIONAL";
508	        return tier + "_" + area;
509	    }
510	
511	    /**
512	     * The region derived from this owner's postcode alone: the region whose fixed
513	     * {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the postcode, or {@code null}
514	     * when the postcode is absent, not four digits, or in no known range. This is the {@code <REGION>}
515	     * component built into the owner's {@linkplain #computeMemberId() memberId} at creation and,
516	     * through it, the source of the owner's {@linkplain #getLocality() locality}. It is the single
517	     * place a region is read from an
518	     * owner's postcode, so every rule keyed by the postcode-derived region shares one derivation.
519	     */
520	    public String getRegion() {
521	        return regionOfPostcode(this.postcode);
522	    }
523	
524	    /**
525	     * The region whose fixed {@linkplain #REGION_POSTCODE_RANGE postcode range} contains the
526	     * given postcode, or {@code null} when the postcode is {@code null}, not four digits, or in
527	     * no known range.
528	     */
529	    private static String regionOfPostcode(String postcode) {
530	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
531	            return null;
532	        }
533	        int value = Integer.parseInt(postcode);
534	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
535	            int[] range = entry.getValue();
536	            if (value >= range[0] && value <= range[1]) {
537	                return entry.getKey();
538	            }
539	        }
540	        return null;
541	    }
542	
543	    /**
544	     * Fixed inclusive 4-digit postcode ranges keyed by region, as {@code {low, high}}:
545	     * {@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}. A region not
546	     * listed here (i.e. {@link #UNKNOWN_REGION}) accepts any 4-digit postcode.
547	     */
548	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
549	        "NSW", new int[] {2000, 2099},
550	        "VIC", new int[] {3000, 3099},
551	        "QLD", new int[] {4000, 4099});
552	
553	    /**
554	     * Whether this owner's postcode is acceptable for its city. Postcode is optional, so a
555	     * {@code null} postcode is accepted. When present it must be four digits and, for a city
556	     * whose {@linkplain #regionOf(String) region} is known, fall within that region's fixed
557	     * inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}); a
558	     * city with no known region accepts any 4-digit postcode.
559	     */
560	    public boolean isPostcodeValid() {
561	        if (this.postcode == null) {
562	            return true;
563	        }
564	        if (!this.postcode.matches("[0-9]{4}")) {
565	            return false;
566	        }
567	        int[] range = REGION_POSTCODE_RANGE.get(regionOf(this.city));
568	        if (range == null) {
569	            return true;
570	        }
571	        int value = Integer.parseInt(this.postcode);
572	        return value >= range[0] && value <= range[1];
573	    }
574	
575	    /**
576	     * The national (subscriber) digit count required by each known country calling code, keyed by
577	     * the code's digits (without the leading {@code '+'}): {@code '+1'} carries 10 national digits
578	     * and {@code '+61'} carries 9. This is the single source of the country-calling-code table,
579	     * shared by every rule keyed by an E.164 number's country code so the mapping is never
580	     * re-derived elsewhere.
581	     */
582	    private static final Map<String, Integer> NATIONAL_DIGITS_BY_COUNTRY = Map.of(
583	        "1", 10,
584	        "61", 9);
585	
586	    /**
587	     * The country calling code (its digits, without the leading {@code '+'}) that prefixes the given
588	     * E.164 digit string, choosing the longest matching code known to
589	     * {@link #NATIONAL_DIGITS_BY_COUNTRY}, or {@code null} when the number begins with no known
590	     * country code. This is the single place a country code is read from an E.164 number, so every
591	     * rule keyed by that code shares one derivation.
592	     */
593	    private static String countryCodeOf(String e164Digits) {
594	        return NATIONAL_DIGITS_BY_COUNTRY.keySet().stream()
595	            .filter(e164Digits::startsWith)
596	            .max(Comparator.comparingInt(String::length))
597	            .orElse(null);
598	    }
599	
600	    /**
601	     * Whether the E.164 digit string (no leading {@code '+'}) carries the national-number length
602	     * required by its {@linkplain #countryCodeOf(String) country calling code}. The longest matching
603	     * known code wins; a number whose country code is not recognised passes this check (its length is
604	     * then governed only by the general E.164 bound), while a recognised code must be followed by
605	     * exactly the national-digit count it requires ({@code '+1'} 10, {@code '+61'} 9).
606	     */
607	    public static boolean hasValidNationalLength(String e164Digits) {
608	        String countryCode = countryCodeOf(e164Digits);
609	        if (countryCode == null) {
610	            return true;
611	        }
612	        return e164Digits.length() - countryCode.length() == NATIONAL_DIGITS_BY_COUNTRY.get(countryCode);
613	    }
614	
615	    /**
616	     * The owner's membership points: they start at 0, gain 2 when an email is present, gain 1 when
617	     * namesakeCount is 0, gain 2 for a {@linkplain #hasLargeHousehold() household of 3 or more}, and
618	     * gain 3 when the owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one
619	     * elapsed fiscal year. The email, namesake and household factors are available on creation; the
620	     * tenure factor is reached only once at least one fiscal-year boundary has passed.
621	     */
622	    public Integer getMembershipPoints() {
623	        int points = 0;
624	        if (hasEmail()) {
625	            points += 2;
626	        }
627	        if (hasNoNamesakes()) {
628	            points += 1;
629	        }
630	        if (hasLargeHousehold()) {
631	            points += 2;
632	        }
633	        if (hasQualifyingTenure()) {
634	            points += 3;
635	        }
636	        return points;
637	    }
638	
639	    /**
640	     * The owner's membership level, a number from 1 to 4. For an owner created through the
641	     * creation pipeline this is the value assigned and stored at creation time; an owner that
642	     * carries no assigned level (e.g. seed data, or an owner not created through that pipeline)
643	     * reports its {@linkplain #getBaseMembershipLevel() base level} derived from its
644	     * membershipPoints. This is the single value read by the API for an owner's membership level.
645	     */
646	    public Integer getMembershipLevel() {
647	        return this.membershipLevel != null ? this.membershipLevel : getBaseMembershipLevel();
648	    }
649	
650	    public void setMembershipLevel(Integer membershipLevel) {
651	        this.membershipLevel = membershipLevel;
652	    }
653	
654	    /**
655	     * The owner's base membership level, a number from 1 to 4 derived directly from
656	     * {@linkplain #getMembershipPoints() membershipPoints}: level 1 for 0-1 points, level 2 for 2-3,
657	     * level 3 for 4-5, and level 4 for 6 or more. This is the level the creation pipeline starts
658	     * from when it assigns the owner's stored {@linkplain #getMembershipLevel() membershipLevel}.
659	     */
660	    public Integer getBaseMembershipLevel() {
661	        int points = getMembershipPoints();
662	        if (points >= 6) {
663	            return 4;
664	        }
665	        if (points >= 4) {
666	            return 3;
667	        }
668	        if (points >= 2) {
669	            return 2;
670	        }
671	        return 1;
672	    }
673	
674	    /**
675	     * Whether this owner belongs to a household of three or more: its {@link #getHouseholdSize()
676	     * householdSize} is {@code 3} or greater. A {@code null} householdSize, meaning the size is not
677	     * known, is treated as not a large household.
678	     */
679	    private boolean hasLargeHousehold() {
680	        return this.householdSize != null && this.householdSize >= 3;
681	    }
682	
683	    /**
684	     * Whether this owner has an email on record: a non-{@code null}, non-empty {@link #getEmail()
685	     * email}. This is the single source of the "has an email" test, shared by every rule keyed by
686	     * email presence so the check is never re-derived elsewhere.
687	     */
688	    private boolean hasEmail() {
689	        return this.email != null && !this.email.isEmpty();
690	    }
691	
692	    /**
693	     * The domain of an email address: the part after the last {@code '@'}, lower-cased, or
694	     * {@code null} when the email is {@code null} or carries no {@code '@'} (an empty local part or
695	     * empty domain is kept as-is). This is the single place an email's domain is read, shared by
696	     * every rule keyed by the email domain so the domain is never re-parsed elsewhere.
697	     */
698	    public static String emailDomainOf(String email) {
699	        if (email == null) {
700	            return null;
701	        }
702	        int at = email.lastIndexOf('@');
703	        if (at < 0) {
704	            return null;
705	        }
706	        return email.substring(at + 1).toLowerCase();
707	    }
708	
709	    /**
710	     * Whether this owner's name is unique in the clinic: its {@link #getNamesakeCount() namesakeCount}
711	     * is {@code 0} (no other owner shares the name). A {@code null} namesakeCount, meaning the count is
712	     * not known, is treated as not unique.
713	     */
714	    private boolean hasNoNamesakes() {
715	        return this.namesakeCount != null && this.namesakeCount == 0;
716	    }
717	
718	    /**
719	     * Whether this owner's {@linkplain #getTenureFiscalYears() tenure} spans at least one elapsed
720	     * fiscal year. A newly created owner (zero elapsed fiscal years) does not qualify; the threshold
721	     * is crossed only once at least one fiscal-year boundary has passed since registration.
722	     */
723	    private boolean hasQualifyingTenure() {
724	        return this.getTenureFiscalYears() >= 1;
725	    }
726	
727	    /**
728	     * The owner's tenure in elapsed fiscal years: the number of fiscal-year boundaries between the
729	     * {@linkplain #fiscalYearOf(LocalDate) fiscal year} of the {@link #registrationDate} and the
730	     * fiscal year of the current date, or {@code 0} when the registrationDate is not yet set (a newly
731	     * created owner has zero tenure). Never negative.
732	     */
733	    public long getTenureFiscalYears() {
734	        if (this.registrationDate == null) {
735	            return 0;
736	        }
737	        return Math.max(0, fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate));
738	    }
739	
740	    /**
741	     * The owner's preferred contact channel: {@code 'EMAIL'} when an email is present,
742	     * otherwise {@code 'PHONE'}.
743	     */
744	    public String getContactPreference() {
745	        return hasEmail() ? "EMAIL" : "PHONE";
746	    }
747	
748	    /**
749	     * The owner's stored E.164 {@linkplain #getTelephone() telephone} formatted for humans:
750	     * a {@code '+'}, the {@linkplain #countryCodeOf(String) country calling code}, a space, and
751	     * the national digits grouped into threes from the left separated by spaces,
752	     * e.g. {@code '+61412345678'} -> {@code '+61 412 345 678'}. The raw {@link #getTelephone()
753	     * telephone} stays in E.164. Returns the telephone unchanged when it is {@code null}, not in
754	     * E.164 form, or carries no known country code.
755	     */
756	    public String getTelephoneDisplay() {
757	        if (this.telephone == null || !this.telephone.startsWith("+")) {
758	            return this.telephone;
759	        }
760	        String digits = this.telephone.substring(1);
761	        String countryCode = countryCodeOf(digits);
762	        if (countryCode == null) {
763	            return this.telephone;
764	        }
765	        String national = digits.substring(countryCode.length());
766	        StringBuilder groups = new StringBuilder();
767	        for (int i = 0; i < national.length(); i += 3) {
768	            if (groups.length() > 0) {
769	                groups.append(' ');
770	            }
771	            groups.append(national, i, Math.min(i + 3, national.length()));
772	        }
773	        return "+" + countryCode + " " + groups;
774	    }
775	
776	    /**
777	     * The owner's identity key: the single derived value used for duplicate detection. It is the
778	     * lower-case hex SHA-256 (64 characters) of the normalized (E.164) telephone, the email
779	     * (already lower-cased, or the empty string when absent) and the {@linkplain #soundex(String)
780	     * soundex} of the lastName, joined with {@code '|'} before hashing, e.g. the digest of
781	     * {@code '+61412345678|jane@example.test|J500'}. Two owners are duplicates, and the second is
782	     * rejected with {@code 409}, only when their whole identity keys are equal.
783	     */
784	    public String getIdentityKey() {
785	        String telephonePart = this.telephone == null ? "" : this.telephone;
786	        String emailPart = this.email == null ? "" : this.email;
787	        String soundexPart = soundex(this.getLastName());
788	        return HashUtils.sha256Hex(telephonePart + "|" + emailPart + "|" + soundexPart);
789	    }
790	
791	    /**
792	     * The American Soundex code of {@code name}: its first letter followed by three digits encoding
793	     * the remaining consonant sounds ({@code b,f,p,v -> 1}; {@code c,g,j,k,q,s,x,z -> 2};
794	     * {@code d,t -> 3}; {@code l -> 4}; {@code m,n -> 5}; {@code r -> 6}; vowels and {@code h,w,y}
795	     * are not coded). Adjacent letters with the same code, and same-coded letters separated only by
796	     * {@code h} or {@code w}, contribute a single digit; a vowel between two same-coded letters
797	     * keeps both. The result is right-padded with zeros and truncated to four characters. Non-letters
798	     * are ignored, and a {@code null} or letter-free name yields the empty string. Used to build the
799	     * owner's {@link #getIdentityKey() identity key} and to group households by surname sound.
800	     */
801	    public static String soundex(String name) {
802	        if (name == null) {
803	            return "";
804	        }
805	        String letters = name.toUpperCase().replaceAll("[^A-Z]", "");
806	        if (letters.isEmpty()) {
807	            return "";
808	        }
809	        StringBuilder code = new StringBuilder();
810	        code.append(letters.charAt(0));
811	        char previous = soundexDigit(letters.charAt(0));
812	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
813	            char c = letters.charAt(i);
814	            char digit = soundexDigit(c);
815	            if (digit != '0' && digit != previous) {
816	                code.append(digit);
817	            }
818	            if (c != 'H' && c != 'W') {
819	                previous = digit;
820	            }
821	        }
822	        while (code.length() < 4) {
823	            code.append('0');
824	        }
825	        return code.toString();
826	    }
827	
828	    /**
829	     * The Soundex digit for a single upper-case letter (see {@link #soundex(String)}), or
830	     * {@code '0'} for a letter that is not coded (a vowel, or {@code h}, {@code w} or {@code y}).
831	     */
832	    private static char soundexDigit(char c) {
833	        switch (c) {
834	            case 'B': case 'F': case 'P': case 'V':
835	                return '1';
836	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
837	                return '2';
838	            case 'D': case 'T':
839	                return '3';
840	            case 'L':
841	                return '4';
842	            case 'M': case 'N':
843	                return '5';
844	            case 'R':
845	                return '6';
846	            default:
847	                return '0';
848	        }
849	    }
850	
851	    protected Set<Pet> getPetsInternal() {
852	        if (this.pets == null) {
853	            this.pets = new HashSet<>();
854	        }
855	        return this.pets;
856	    }
857	
858	    protected void setPetsInternal(Set<Pet> pets) {
859	        this.pets = pets;
860	    }
861	
862	    public List<Pet> getPets() {
863	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
864	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
865	        return Collections.unmodifiableList(sortedPets);
866	    }
867	
868	    public void setPets(List<Pet> pets) {
869	        this.pets = new HashSet<>(pets);
870	    }
871	
872	    public void addPet(Pet pet) {
873	        getPetsInternal().add(pet);
874	        pet.setOwner(this);
875	    }
876	
877	    /**
878	     * Return the Pet with the given name, or null if none found for this Owner.
879	     *
880	     * @param name to test
881	     * @return true if pet name is already in use
882	     */
883	    public Pet getPet(String name) {
884	        return getPet(name, false);
885	    }
886	
887	    /**
888	     * Return the Pet with the given name, or null if none found for this Owner.
889	     *
890	     * @param name to test
891	     * @return true if pet name is already in use
892	     */
893	    public Pet getPet(String name, boolean ignoreNew) {
894	        name = name.toLowerCase();
895	        for (Pet pet : getPetsInternal()) {
896	            if (!ignoreNew || !pet.isNew()) {
897	                String compName = pet.getName();
898	                compName = compName.toLowerCase();
899	                if (compName.equals(name)) {
900	                    return pet;
901	                }
902	            }
903	        }
904	        return null;
905	    }
906	
907	    public Pet getPet(Integer petId) {
908	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
909	    }
910	
911	    @Override
912	    public String toString() {
913	        return new ToStringCreator(this)
914	
915	            .append("id", this.getId())
916	            .append("new", this.isNew())
917	            .append("lastName", this.getLastName())
918	            .append("firstName", this.getFirstName())
919	            .append("address", this.address)
920	            .append("city", this.city)
921	            .append("telephone", this.telephone)
922	            .append("email", this.email)
923	            .toString();
924	    }
925	}
