123	    /**
124	     * The HTTP request header a client may send to make a create idempotent. When a create repeats
125	     * with a key already seen, the originally created owner is returned instead of a duplicate.
126	     */
127	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
128	
129	    /**
130	     * Remembers, per {@link #IDEMPOTENCY_KEY_HEADER Idempotency-Key}, the id of the owner that key's
131	     * first successful create produced, so a repeat of that create can return the same owner rather
132	     * than creating a duplicate.
133	     */
134	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
