194	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
195	    @Override
196	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
197	        String idempotencyKey = currentIdempotencyKey();
198	        if (idempotencyKey != null) {
199	            Integer existingId = idempotentCreates.get(idempotencyKey);
200	            if (existingId != null) {
201	                Owner existing = this.clinicService.findOwnerById(existingId);
202	                if (existing != null) {
203	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
204	                }
205	            }
206	        }
207	
208	        ResponseEntity<OwnerDto> response = createOwner(ownerFieldsDto);
209	
210	        if (idempotencyKey != null && response.getStatusCode() == HttpStatus.CREATED
211	            && response.getBody() != null && response.getBody().getId() != null) {
212	            idempotentCreates.put(idempotencyKey, response.getBody().getId());
213	        }
214	        return response;
215	    }
