217	    /**
218	     * The non-blank {@link #IDEMPOTENCY_KEY_HEADER Idempotency-Key} header of the request currently
219	     * being handled, or {@code null} when the request carries no such header (or no request is bound
220	     * to the current thread). Used to make a repeated create return the originally created owner.
221	     */
222	    private String currentIdempotencyKey() {
223	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
224	            return null;
225	        }
226	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
227	        return (key == null || key.isBlank()) ? null : key;
228	    }
