230	    /**
231	     * Run the full owner-creation pipeline for a submitted {@link OwnerFieldsDto} and build its
232	     * response. The submitted fields are mapped to an {@link Owner}, which is
233	     * {@link #normalizeAndValidate(Owner) normalized and validated}, checked against the
234	     * {@link #isDailyLimitReached(LocalDate) daily creation limit}, {@link #assignHousehold(Owner)
235	     * assigned its household} and screened for {@link #checkForConflicts(Owner) conflicts};
236	     * a surviving owner then has its {@link #assignDerivedAttributes(Owner, boolean) derived
237	     * attributes} assigned, is persisted and audited. Returns the {@link #created(Owner) 201 Created}
238	     * response for the persisted owner, or throws {@link RejectedRequestException} with the status
239	     * the create must fail with ({@code 400 Bad Request}, {@code 429 Too Many Requests} or
240	     * {@code 409 Conflict}) when the owner cannot be created.
241	     */
242	    private ResponseEntity<OwnerDto> createOwner(OwnerFieldsDto ownerFieldsDto) {
243	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
244	
245	        normalizeAndValidate(owner);
246	        if (isDailyLimitReached(owner.getRegistrationDate())) {
247	            throw new RejectedRequestException(HttpStatus.TOO_MANY_REQUESTS);
248	        }
249	
250	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
251	        assignHousehold(owner);
252	
253	        checkForConflicts(owner);
254	
255	        assignDerivedAttributes(owner, sharesHousehold);
256	        this.clinicService.saveOwner(owner);
257	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
258	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
259	            owner.getMembershipLevel());
260	        emitOwnerCreatedEvent(owner);
261	        enqueueWelcomeNotification(owner);
262	        return created(owner);
263	    }
