265	    /**
266	     * Enqueue a welcome notification for a just-created owner by emitting a line on the {@code NOTIFY}
267	     * logger that carries the owner's id and its unified {@link Owner#getMemberId() memberId}, so a
268	     * downstream consumer can address the welcome to the newly registered owner.
269	     */
270	    private void enqueueWelcomeNotification(Owner owner) {
271	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
272	    }
