274	    /**
275	     * Emit the immutable {@link OwnerCreatedEvent} for a just-persisted owner as a JSON object on the
276	     * {@code AUDIT} logger. A fresh {@link #AUDIT_SEQ monotonic sequence} is stamped onto the event so
277	     * the order of creates is recoverable from the audit stream. The event carries the owner's primary
278	     * identifier, its unified memberId.
279	     */
280	    private void emitOwnerCreatedEvent(Owner owner) {
281	        OwnerCreatedEvent event = OwnerCreatedEvent.of(AUDIT_SEQ.incrementAndGet(), owner);
282	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
283	    }
