285	    /**
286	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
287	     * rejected. The owner's {@link #normalizeAddress(Owner) address is normalized} (a missing address
288	     * is rejected), its telephone is converted to E.164 (an unconvertible number is rejected), its
289	     * postcode is checked against its city's region, a registration date in the future is rejected,
290	     * and the effective registration date (the supplied one, or today when none was given) is rolled
291	     * onto a business day and stored back on the owner. Returns once the owner is valid and
292	     * normalized, or throws {@link RejectedRequestException} with the status the create must fail
293	     * with ({@code 400 Bad Request}) otherwise.
294	     */
295	    private void normalizeAndValidate(Owner owner) {
296	        if (!normalizeAddress(owner)) {
297	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST);
298	        }
299	        String telephone = toE164(owner.getTelephone());
300	        if (telephone == null) {
301	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST);
302	        }
303	        owner.setTelephone(telephone);
304	        if (isDisposableEmail(owner.getEmail())) {
305	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST);
306	        }
307	        if (!owner.isPostcodeValid()) {
308	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST);
309	        }
310	        if (owner.getRegistrationDate() != null
311	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
312	            throw new RejectedRequestException(HttpStatus.BAD_REQUEST);
313	        }
314	        LocalDate effectiveDate = owner.getRegistrationDate() != null
315	            ? owner.getRegistrationDate() : LocalDate.now();
316	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
317	    }
318	
319	    /**
320	     * Normalize the owner's supplied address into its canonical stored form and report whether an
321	     * address was supplied at all. The owner may supply its address either as the structured
322	     * {@code addressLine1}/{@code addressLine2} fields or as the flat {@code address} field, which is
323	     * kept for backward compatibility; the structured form is preferred whenever a non-blank
324	     * {@code addressLine1} is present. Each supplied field is run through the {@link AddressNormalizer}
325	     * (trimmed, whitespace-collapsed, upper-cased, common street-type abbreviations expanded). When the
326	     * structured form is used, the normalized {@code addressLine1} and {@code addressLine2} are stored
327	     * back and the composed {@link Owner#getAddress() address} becomes the normalized
328	     * {@code addressLine1} with a single space and the normalized {@code addressLine2} appended when an
329	     * {@code addressLine2} is present; when the flat form is used, the normalized flat address is
330	     * stored and no structured lines are kept. Returns {@code true} once a non-blank address has been
331	     * normalized and stored, or {@code false} when neither form supplied an address, in which case the
332	     * create must be rejected with {@code 400 Bad Request}.
333	     */
334	    private boolean normalizeAddress(Owner owner) {
335	        String line1 = addressNormalizer.normalize(owner.getAddressLine1());
336	        if (!line1.isEmpty()) {
337	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
338	            owner.setAddressLine1(line1);
339	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
340	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
341	            return true;
342	        }
343	        String address = addressNormalizer.normalize(owner.getAddress());
344	        if (address.isEmpty()) {
345	            return false;
346	        }
347	        owner.setAddressLine1(null);
348	        owner.setAddressLine2(null);
349	        owner.setAddress(address);
350	        return true;
351	    }
