353	    /**
354	     * The set of disposable (throwaway) email domains that an owner's email may not use. An owner
355	     * whose email is hosted on one of these domains is rejected with {@code 400 Bad Request}.
356	     */
357	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
