360	    /**
361	     * Whether the given email is hosted on a {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable}
362	     * domain. The email is optional, so a {@code null} or empty email is not disposable; otherwise
363	     * its {@linkplain Owner#emailDomainOf(String) domain} (compared case-insensitively) is matched
364	     * against the blocklist.
365	     */
366	    private boolean isDisposableEmail(String email) {
367	        String domain = Owner.emailDomainOf(email);
368	        return domain != null && DISPOSABLE_EMAIL_DOMAINS.contains(domain);
369	    }
