384	    /**
385	     * Screen the owner for a clash with an owner that already exists. An owner is rejected with
386	     * {@code 409 Conflict} when it {@linkplain #isDuplicateIdentity(Owner) duplicates an existing
387	     * owner's identity key} or when its {@link #isCityAtCapacity(String) city is already at
388	     * capacity}. Sharing a household (the same surname sound and postcode) but with a different
389	     * identity key is not a conflict: such an owner is admitted and later
390	     * {@linkplain #findSoftDuplicate(Owner) flagged as a possible duplicate}. Returns when the owner
391	     * clashes with nothing and may be created, or throws {@link RejectedRequestException} with
392	     * {@code 409 Conflict} when it clashes.
393	     */
394	    private void checkForConflicts(Owner owner) {
395	        if (isDuplicateIdentity(owner)) {
396	            throw new RejectedRequestException(HttpStatus.CONFLICT);
397	        }
398	        if (isCityAtCapacity(owner.getCity())) {
399	            throw new RejectedRequestException(HttpStatus.CONFLICT);
400	        }
401	    }
