403	    /**
404	     * Whether an existing owner already carries this owner's {@link Owner#getIdentityKey() identity
405	     * key}. This is the single hard-duplicate rule: two owners are duplicates exactly when their
406	     * identity keys are equal, and the second is rejected with {@code 409 Conflict}. Like the other
407	     * identity rules it considers only the {@linkplain #activeOwners() active owners}, so an owner
408	     * flagged {@linkplain Owner#isDeleted() deleted} never triggers a duplicate. The email-domain
409	     * blocklist is applied earlier, during {@link #normalizeAndValidate(Owner) validation}, so a
410	     * disposable-email owner is rejected before it reaches this check.
411	     */
412	    private boolean isDuplicateIdentity(Owner owner) {
413	        String identityKey = owner.getIdentityKey();
414	        return activeOwners().stream()
415	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
416	    }
