439	    private void assignDerivedAttributes(Owner owner, boolean sharesHousehold) {
440	        owner.setMemberId(memberId(owner));
441	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
442	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
