450	    /**
451	     * Whether a newly created owner should be flagged for review. True when any of these hold: the
452	     * owner is a {@linkplain Owner#getPossibleDuplicate() possible duplicate}, its email domain is
453	     * {@linkplain #isDisposableAdjacentEmail(String) disposable-adjacent}, or its city is over its
454	     * soft capacity (the city is {@linkplain #isCityApproachingCapacity(String) approaching capacity},
455	     * so its {@link Owner#getCapacityWarning() capacityWarning} is set); otherwise false. Computed
456	     * during {@link #assignDerivedAttributes(Owner, boolean)}, after the possible-duplicate and
457	     * capacity-warning attributes it reads have already been assigned.
458	     */
459	    private boolean isRiskFlagged(Owner owner) {
460	        return Boolean.TRUE.equals(owner.getPossibleDuplicate())
461	            || isDisposableAdjacentEmail(owner.getEmail())
462	            || Boolean.TRUE.equals(owner.getCapacityWarning());
463	    }
