465	    /**
466	     * Whether the given email's domain is disposable-adjacent: a subdomain of a known
467	     * {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable} domain (e.g. {@code x.mailinator.com}). An
468	     * exactly-disposable domain is rejected earlier during {@link #normalizeAndValidate(Owner)
469	     * validation}, so it never reaches here; a subdomain is admitted but still flagged as adjacent.
470	     * The email is optional, so a {@code null} or empty email is not disposable-adjacent; otherwise
471	     * its {@linkplain Owner#emailDomainOf(String) domain} (compared case-insensitively) is tested.
472	     */
473	    private boolean isDisposableAdjacentEmail(String email) {
474	        String domain = Owner.emailDomainOf(email);
475	        if (domain == null) {
476	            return false;
477	        }
478	        return DISPOSABLE_EMAIL_DOMAINS.stream()
479	            .anyMatch(disposable -> domain.endsWith("." + disposable));
480	    }
