482	    /**
483	     * The membership level to assign a newly created owner and store on it as its
484	     * {@link Owner#getMembershipLevel() membershipLevel}: the owner's own
485	     * {@linkplain Owner#getBaseMembershipLevel() base level} derived from its membershipPoints,
486	     * capped so it cannot exceed one above the current maximum membershipLevel among the owner's
487	     * existing {@linkplain #householdMembers(String) household members}. With no existing household
488	     * member no cap applies and the base level is used as-is. This is the single place the stored
489	     * membership level is derived; it runs during {@link #assignDerivedAttributes(Owner, boolean)},
490	     * after the owner has passed the duplicate and capacity checks and so has its household members
491	     * available to it.
492	     */
493	    private Integer membershipLevel(Owner owner) {
494	        int base = owner.getBaseMembershipLevel();
495	        Collection<Owner> members = householdMembers(owner.getHouseholdId());
496	        if (members.isEmpty()) {
497	            return base;
498	        }
499	        int householdMax = members.stream()
500	            .mapToInt(Owner::getMembershipLevel)
501	            .max()
502	            .getAsInt();
503	        return Math.min(base, householdMax + 1);
504	    }
