506	    /**
507	     * Flag a newly created owner as a possible (soft) duplicate. An owner that declares it shares a
508	     * household ({@code sharesHousehold}) is a declared household member, not a suspected duplicate,
509	     * so it is never flagged. Otherwise it is flagged only when it is a soft match of an existing
510	     * owner as determined by {@link #findSoftDuplicate(Owner)}. When such an owner exists the new owner is flagged with
511	     * {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set to that owner's id;
512	     * otherwise {@code possibleDuplicate = false} and no matching id is recorded.
513	     */
514	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
515	        Owner match = sharesHousehold ? null : findSoftDuplicate(owner);
516	        owner.setPossibleDuplicate(match != null);
517	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
518	    }
519	
520	    /**
521	     * The owners a newly created owner is checked against by the duplicate and identity rules:
522	     * the {@link #householdMembers(String) household} membership and {@link #findSoftDuplicate(Owner)
523	     * soft-duplicate} checks, the {@link #memberId(Owner) memberId} de-duplication and the
524	     * {@link #namesakeCount(String, String) namesake} count. This is the single place that scope is
525	     * defined, so every one of those rules considers exactly the same set of owners; it spans every
526	     * owner the clinic holds except those flagged {@linkplain Owner#isDeleted() deleted}, which a
527	     * soft delete retains but excludes from duplicate and identity detection.
528	     */
529	    private Collection<Owner> activeOwners() {
530	        return this.clinicService.findAllOwners().stream()
531	            .filter(owner -> !owner.isDeleted())
532	            .collect(Collectors.toList());
533	    }
534	
535	    /**
536	     * The existing owner this owner softly duplicates, or {@code null} when there is none. A soft
537	     * match is an existing owner whose {@link Owner#getIdentityKey() identity key} differs from this
538	     * owner's (so it is not already a hard duplicate) but whose lastName has the same
539	     * {@link Owner#soundex(String) soundex} and whose postcode matches; the earliest such owner (by
540	     * id) is returned. Two owners sharing a surname sound and postcode but differing in telephone (or
541	     * email) therefore surface here as a soft match rather than being rejected. A postcode is required
542	     * for a soft match, so an owner without a postcode never matches.
543	     */
544	    private Owner findSoftDuplicate(Owner owner) {
545	        if (owner.getPostcode() == null) {
546	            return null;
547	        }
548	        String candidateSoundex = Owner.soundex(owner.getLastName());
549	        String identityKey = owner.getIdentityKey();
550	        return activeOwners().stream()
551	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
552	            .filter(existing -> Owner.soundex(existing.getLastName()).equals(candidateSoundex))
553	            .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
554	            .min(Comparator.comparingInt(Owner::getId))
555	            .orElse(null);
556	    }
557	
558	    /**
559	     * Build the memberId for a newly created owner, formatted {@code '<REGION><FY><HASH8><CHK>'}: the
560	     * region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION} when the postcode is
561	     * absent or maps to no known region), the 2-digit fiscal-year code FY of the business-day-adjusted
562	     * registrationDate, the first 8 upper-case hex characters HASH8 of the SHA-256 of the normalized
563	     * (E.164) telephone concatenated with the lastName, and a single Luhn check digit CHK over the
564	     * decimal digits of {@code <REGION><FY><HASH8>} (e.g. {@code 'NSW273C1A9F2B4'}). The
565	     * {@code <REGION><FY><HASH8><CHK>} value is computed by {@link Owner#computeMemberId()}; this is
566	     * the single source of the owner's identity, from which the owner's locality and fiscal year are
567	     * read back.
568	     *
569	     * <p>When the computed memberId collides with an existing owner's {@code memberId}, a
570	     * {@code '-<n>'} suffix is appended with the smallest {@code n} of 2 or more that makes the
571	     * memberId unique, and the de-duplicated memberId is returned.
572	     */
573	    private String memberId(Owner owner) {
574	        String base = owner.computeMemberId();
575	
576	        Set<String> existingIds = activeOwners().stream()
577	            .map(Owner::getMemberId)
578	            .filter(Objects::nonNull)
579	            .collect(Collectors.toSet());
580	
581	        if (!existingIds.contains(base)) {
582	            return base;
583	        }
584	        int n = 2;
585	        while (existingIds.contains(base + "-" + n)) {
586	            n++;
587	        }
588	        return base + "-" + n;
589	    }
590	
591	    /**
592	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
593	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
594	     * (business-day) registration date of the owner being created, so owners are counted per
595	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
596	     */
597	    private boolean isDailyLimitReached(LocalDate day) {
598	        long count = this.clinicService.findAllOwners().stream()
599	            .filter(existing -> day.equals(existing.getRegistrationDate()))
600	            .count();
601	        return count >= 100;
602	    }
603	
604	    /**
605	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
606	     * more than 80 owners have already been created for the given business day. Counts the owners
607	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
608	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
609	     * warning.
610	     */
611	    private boolean isBulkSignup(LocalDate day) {
612	        long count = this.clinicService.findAllOwners().stream()
613	            .filter(existing -> day.equals(existing.getRegistrationDate()))
614	            .count();
615	        return count > 80;
616	    }
617	
618	    /**
619	     * Roll a registration date forward onto a business day: when it falls on a Saturday, Sunday or a
620	     * listed public holiday, advance it to the next non-holiday weekday; an ordinary weekday is
621	     * returned unchanged.
622	     */
623	    private LocalDate toBusinessDay(LocalDate date) {
624	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
625	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
626	            || PUBLIC_HOLIDAYS.contains(date)) {
627	            date = date.plusDays(1);
628	        }
629	        return date;
630	    }
631	
632	    /**
633	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
634	     * more owners. Cities are compared case-insensitively.
635	     */
636	    private boolean isCityAtCapacity(String city) {
637	        return cityOwnerCount(city) >= 50;
638	    }
639	
640	    /**
641	     * Whether the given city is approaching its owner capacity, i.e. it already contains between 40
642	     * and 49 owners (inclusive) and so is nearing the {@link #isCityAtCapacity(String) hard capacity
643	     * limit} of 50. When true, a newly created owner in that city is flagged with a
644	     * {@code capacityWarning}; the hard rejection at 50 is unchanged. Cities are compared
645	     * case-insensitively.
646	     */
647	    private boolean isCityApproachingCapacity(String city) {
648	        long count = cityOwnerCount(city);
649	        return count >= 40 && count <= 49;
650	    }
651	
652	    /**
653	     * The number of existing owners in the given city, compared case-insensitively. Counted over the
654	     * owners present before this create.
655	     */
656	    private long cityOwnerCount(String city) {
657	        return this.clinicService.findAllOwners().stream()
658	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
659	            .count();
660	    }
661	
662	    /**
663	     * The number of existing owners that already share the given firstName and lastName,
664	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
665	     * whitespace runs collapsed). Counted over the owners present before this create.
666	     */
667	    private int namesakeCount(String firstName, String lastName) {
668	        String candidateFirstName = normalizeName(firstName);
669	        String candidateLastName = normalizeName(lastName);
670	        return (int) activeOwners().stream()
671	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
672	                && normalizeName(existing.getLastName()).equals(candidateLastName))
673	            .count();
674	    }
675	
676	    /**
677	     * The number of members in this owner's household after this create: the count of existing
678	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
679	     * created. An owner with no household ({@code householdId == null}) is a household of one.
680	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
681	     * does not depend on the order in which household members were created.
682	     */
683	    private int householdSize(String householdId) {
684	        if (householdId == null) {
685	            return 1;
686	        }
687	        long existing = this.clinicService.findAllOwners().stream()
688	            .filter(other -> householdId.equals(other.getHouseholdId()))
689	            .count();
690	        return (int) existing + 1;
691	    }
692	
693	    /**
694	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
695	     * cannot form a valid E.164 number.
696	     *
697	     * <p>A leading '+' and country code are kept when present; otherwise country code
698	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
699	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
700	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
701	     * exactly the national-digit count that code requires (see
702	     * {@link Owner#hasValidNationalLength}); otherwise it is rejected as invalid.
703	     */
704	    private String toE164(String telephone) {
705	        if (telephone == null) {
706	            return null;
707	        }
708	        boolean hasCountryCode = telephone.trim().startsWith("+");
709	        String digits = telephone.replaceAll("\\D", "");
710	        String e164;
711	        if (hasCountryCode) {
712	            e164 = digits;
713	        } else {
714	            if (digits.startsWith("0")) {
715	                digits = digits.substring(1);
716	            }
717	            e164 = "61" + digits;
718	        }
719	        if (e164.length() < 8 || e164.length() > 15) {
720	            return null;
721	        }
722	        if (!Owner.hasValidNationalLength(e164)) {
723	            return null;
724	        }
725	        return "+" + e164;
726	    }
727	
728	    /**
729	     * The existing owners already registered in the household identified by {@code householdId}: the
730	     * {@linkplain #activeOwners() active owners} carrying that same non-null householdId. The owner
731	     * being created is not yet persisted, so it is never among them, and a {@code null} householdId
732	     * (an owner with no household) yields an empty collection. This is the single source of a
733	     * household's existing membership, shared by every rule keyed by an owner's household (the
734	     * {@link #membershipLevel(Owner) membership-level} derivation) so the set is never re-derived
735	     * elsewhere; like the other identity rules it ignores {@linkplain Owner#isDeleted() deleted}
736	     * owners.
737	     */
738	    private Collection<Owner> householdMembers(String householdId) {
739	        if (householdId == null) {
740	            return List.of();
741	        }
742	        return activeOwners().stream()
743	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
744	            .collect(Collectors.toList());
745	    }
746	
747	    /**
748	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
749	     * to a single space and lower-case. A null value normalizes to the empty string.
750	     */
751	    private String normalizeName(String value) {
752	        if (value == null) {
753	            return "";
754	        }
755	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
756	    }
757	
758	    /**
759	     * A stable shared identifier for the household an owner belongs to, derived deterministically
760	     * from its lastName and postcode. The lastName is normalized (case-insensitive,
761	     * whitespace-collapsed) before hashing, so every owner sharing the same lastName and postcode is
762	     * assigned the same value regardless of the order in which they are created. Formatted as the
763	     * first 12 upper-case hex characters of the SHA-256 of {@code '<normalizedLastName>|<postcode>'}
764	     * (an absent postcode contributes the empty string).
765	     */
766	    private String householdId(Owner owner) {
767	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
768	        String key = normalizeName(owner.getLastName()) + "|" + postcode;
769	        return shaHexUpper(key).substring(0, 12);
770	    }
771	
772	    /**
773	     * The upper-case rendering of the {@linkplain HashUtils#sha256Hex(String) SHA-256 hex} of
774	     * {@code input} (two hex characters per digest byte, so 64 characters in all). Callers that
775	     * need a shorter opaque token take a prefix of the result (e.g. {@link #householdId} keeps the
776	     * first 12 characters). The hashing itself lives in {@link HashUtils} so the one implementation is
777	     * shared with the owner's {@link Owner#getIdentityKey() identity key} and its
778	     * {@link Owner#computeMemberId() memberId} HASH8.
779	     */
780	    private String shaHexUpper(String input) {
781	        return HashUtils.sha256Hex(input).toUpperCase();
782	    }
783	
784	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
785	    @Override
786	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
787	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
788	        if (currentOwner == null) {
789	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
790	        }
791	        currentOwner.setAddress(ownerFieldsDto.getAddress());
792	        currentOwner.setCity(ownerFieldsDto.getCity());
793	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
794	        currentOwner.setLastName(ownerFieldsDto.getLastName());
795	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
796	        this.clinicService.saveOwner(currentOwner);
797	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
798	    }
799	
800	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
801	    @Transactional
802	    @Override
803	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
804	        Owner owner = this.clinicService.findOwnerById(ownerId);
805	        if (owner == null) {
806	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
807	        }
808	        this.clinicService.deleteOwner(owner);
809	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
810	    }
811	
812	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
813	    @Override
814	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
815	        Owner owner = this.clinicService.findOwnerById(ownerId);
816	        if (owner == null) {
817	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
818	        }
819	        HttpHeaders headers = new HttpHeaders();
820	        Pet pet = petMapper.toPet(petFieldsDto);
821	        owner.setId(ownerId);
822	        pet.setOwner(owner);
823	        pet.getType().setName(null);
824	        this.clinicService.savePet(pet);
825	        PetDto petDto = petMapper.toPetDto(pet);
826	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
827	            .buildAndExpand(pet.getId()).toUri());
828	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
829	    }
830	
831	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
832	    @Override
833	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
834	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
835	        if (currentOwner != null) {
836	            Pet currentPet = this.clinicService.findPetById(petId);
837	            if (currentPet != null) {
838	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
839	                currentPet.setName(petFieldsDto.getName());
840	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
841	                this.clinicService.savePet(currentPet);
842	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
843	            }
844	        }
845	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
846	    }
847	
848	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
849	    @Override
850	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
851	        HttpHeaders headers = new HttpHeaders();
852	        Visit visit = visitMapper.toVisit(visitFieldsDto);
853	        Pet pet = new Pet();
854	        pet.setId(petId);
855	        visit.setPet(pet);
856	        this.clinicService.saveVisit(visit);
857	        VisitDto visitDto = visitMapper.toVisitDto(visit);
858	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
859	            .buildAndExpand(visit.getId()).toUri());
860	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
861	    }
862	
863	
864	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
865	    @Override
866	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
867	        Owner owner = this.clinicService.findOwnerById(ownerId);
868	        if (owner != null) {
869	            Pet pet = owner.getPet(petId);
870	            if (pet != null) {
871	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
872	            }
873	        }
874	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
875	    }
876	}
